import React from 'react';
import { Link } from 'react-router-dom'; // Wichtig: Link statt <a>
import 'bootstrap/dist/js/bootstrap.bundle.min';

/* 
Header-Konfiguration:
- Name-Schriftgröße: fs-2 (ca. 1.5rem / 24px)
- Navigations-Schriftgröße: 1rem (ca. 16px)
- Farbe Hintergrund:rgb(255, 255, 255) (blau)
-Padding links/rechts: 200px
*/

function Footer() {
  return (
    <footer className="text-center text-lg-start py-3" style={{ backgroundColor: '#001d2e' }}>
      <nav className="mb-2">
        <ul className="nav justify-content-center">
          <li className="nav-item">
            <Link className="nav-link fw-semibold" style={{ color: 'white', fontSize: '1rem' }} to="/">
              Home
            </Link>
          </li>
          <li className="nav-item">
            <Link className="nav-link fw-semibold" style={{ color: 'white', fontSize: '1rem' }} to="/impressum">
              Impressum & Datenschutz
            </Link>
          </li>
        </ul>
      </nav>

      {/* --- AB HIER NEU --- */}
      <div className="text-center small mt-2" style={{ color: '#a0aec0' }}>
        Created with <span style={{ color: '#e25555' }}>❤️</span> using <strong>React</strong> & <strong>Bootstrap</strong> • © 2026 Felix Urban
      </div>
      {/* ------------------- */}

    </footer>
  );
}

export default Footer;
